        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // admissible domain: feeRate must be within allowed bound for initialize to succeed on reference
        // The reference reverts if _feeRate > 5000, so constrain to <= 5000 so reference always accepts inputs.
        vm.assume(_feeRate <= 5000);

        bool ok;

        // call initialize and observe whether it returns or reverts
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the correct contract the call must succeed and set initialized == true.
        // The mutant may revert (ok == false) for some inputs, violating this property.
        assertTrue(ok && c.initialized());
    }
}
